// Build S3 image URL from the current event id
const base = 'https://flomo-test.s3.eu-north-1.amazonaws.com';

return items.map(item => ({
  json: {
    ...item.json,
    pictureUrl: `${base}/${item.json.id}.jpg`
  },
  binary: item.binary
}));

return items.map(item => ({
  json: {
    ...item.json,
    startedAtIso: new Date().toISOString(),
    startedAtMs: Date.now()
  },
  binary: item.binary
}));

function safeUsageAt(nodeName, idx) {
  try {
    const all = $(nodeName).all();
    const r = all[idx]?.json?.body ?? all[idx]?.json;

    return {
      model: r?.model ?? null,
      inputTokens: Number(r?.usage?.input_tokens || 0),
      cachedInputTokens: Number(r?.usage?.input_tokens_details?.cached_tokens || 0),
      outputTokens: Number(r?.usage?.output_tokens || 0),
      totalTokens: Number(r?.usage?.total_tokens || 0),
      used: !!r
    };
  } catch {
    return {
      model: null,
      inputTokens: 0,
      cachedInputTokens: 0,
      outputTokens: 0,
      totalTokens: 0,
      used: false
    };
  }
}

function getPricingEur(model) {
  const m = String(model || '').toLowerCase();

  // Your current code is using a fixed USD -> EUR factor
  const USD_TO_EUR = 0.8672275;

  const toEur = (usd) => Number((usd * USD_TO_EUR).toFixed(6));

  if (m.includes('gpt-5-mini')) {
    return {
      inputPer1M: toEur(0.25),
      cachedInputPer1M: toEur(0.025),
      outputPer1M: toEur(2.00)
    };
  }

  if (m.includes('gpt-5-nano')) {
    return {
      inputPer1M: toEur(0.05),
      cachedInputPer1M: toEur(0.005),
      outputPer1M: toEur(0.40)
    };
  }

  // Must come after mini/nano so they don't get caught here
  if (m.includes('gpt-5')) {
    return {
      inputPer1M: toEur(1.25),
      cachedInputPer1M: toEur(0.125),
      outputPer1M: toEur(10.00)
    };
  }

  return {
    inputPer1M: 0,
    cachedInputPer1M: 0,
    outputPer1M: 0
  };
}

function calcCostEur(u) {
  const p = getPricingEur(u.model);

  const cachedInput = Math.min(u.cachedInputTokens || 0, u.inputTokens || 0);
  const uncachedInput = Math.max(0, (u.inputTokens || 0) - cachedInput);

  const inputCostEur =
    (uncachedInput / 1_000_000) * p.inputPer1M +
    (cachedInput / 1_000_000) * p.cachedInputPer1M;

  const outputCostEur =
    ((u.outputTokens || 0) / 1_000_000) * p.outputPer1M;

  return {
    inputCostEur,
    outputCostEur,
    totalCostEur: inputCostEur + outputCostEur
  };
}

const currentItems = $input.all();
const startItems = $('Init Test Metrics').all();

return currentItems.map((item, idx) => {
  const startNode = startItems[idx]?.json ?? {};

  const startedAtIso = startNode.startedAtIso ?? null;
  const startedAtMs = Number(startNode.startedAtMs || 0);

  const finishedAtIso = new Date().toISOString();
  const finishedAtMs = Date.now();
  const latencyMs = startedAtMs ? (finishedAtMs - startedAtMs) : null;
  const latencySec = latencyMs ? Number((latencyMs / 1000).toFixed(2)) : null;

  const u1 = safeUsageAt('Find Vehicle', idx);
  const u2 = safeUsageAt('LPN Review', idx);
  const u3 = safeUsageAt('Final LPN', idx);

  const usages = [u1, u2, u3].filter(u => u.used);

  const openAiCallCount = usages.length;
  const inputTokens = usages.reduce((s, u) => s + u.inputTokens, 0);
  const cachedInputTokens = usages.reduce((s, u) => s + u.cachedInputTokens, 0);
  const outputTokens = usages.reduce((s, u) => s + u.outputTokens, 0);
  const totalTokens = usages.reduce((s, u) => s + u.totalTokens, 0);

  const modelCounts = {};
  const costByModel = {};

  let inputCostEur = 0;
  let outputCostEur = 0;
  let totalCostEur = 0;

  for (const u of usages) {
    if (u.model) {
      modelCounts[u.model] = (modelCounts[u.model] || 0) + 1;
    }

    const c = calcCostEur(u);

    inputCostEur += c.inputCostEur;
    outputCostEur += c.outputCostEur;
    totalCostEur += c.totalCostEur;

    if (u.model) {
      costByModel[u.model] ??= {
        calls: 0,
        inputTokens: 0,
        cachedInputTokens: 0,
        outputTokens: 0,
        totalTokens: 0,
        inputCostEur: 0,
        outputCostEur: 0,
        totalCostEur: 0
      };

      costByModel[u.model].calls += 1;
      costByModel[u.model].inputTokens += u.inputTokens;
      costByModel[u.model].cachedInputTokens += u.cachedInputTokens;
      costByModel[u.model].outputTokens += u.outputTokens;
      costByModel[u.model].totalTokens += u.totalTokens;
      costByModel[u.model].inputCostEur += c.inputCostEur;
      costByModel[u.model].outputCostEur += c.outputCostEur;
      costByModel[u.model].totalCostEur += c.totalCostEur;
    }
  }

  const modelsUsed = Object.keys(modelCounts).join(' | ');

  return {
    json: {
      eventId: item.json.eventId ?? null,
      startedAt: startedAtIso,
      finishedAt: finishedAtIso,
      latencyMs,
      latencySec,

      openAiCallCount,
      modelsUsed,
      modelCounts: JSON.stringify(modelCounts),

      inputTokens,
      cachedInputTokens,
      outputTokens,
      totalTokens,
      candidateCount: item.json.candidateCount ?? null,

      inputCostEur: Number(inputCostEur.toFixed(6)),
      outputCostEur: Number(outputCostEur.toFixed(6)),
      totalCostEur: Number(totalCostEur.toFixed(6)),
      costByModel: JSON.stringify(
        Object.fromEntries(
          Object.entries(costByModel).map(([model, v]) => [
            model,
            {
              ...v,
              inputCostEur: Number(v.inputCostEur.toFixed(6)),
              outputCostEur: Number(v.outputCostEur.toFixed(6)),
              totalCostEur: Number(v.totalCostEur.toFixed(6))
            }
          ])
        )
      ),

      decision: item.json.decision ?? 'N.A.',
      finalPlate: String(item.json.finalPlate || 'n.a.'),
      chosenRank: item.json.chosenRank ?? null,
      selectedFromProvided: item.json.selectedFromProvided ?? null,
      confidence: item.json.confidence ?? null,
      reason: item.json.reason ?? null
    }
  };
});

const expectedByEventId = {
  "CASE_001": "EXPECTED_001",
  "CASE_002": "EXPECTED_002",
  "CASE_003": "EXPECTED_003"
};

function normalizeForCompare(value) {
  return String(value || '')
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, '');
}

return items.map(item => {
  const eventId = item.json.eventId ?? $('Loop Over Items').first().json.id;
  const expectedLpn = expectedByEventId[eventId] ?? null;
  const actualNormalized = normalizeForCompare(item.json.finalPlate);
  const expectedNormalized = normalizeForCompare(expectedLpn);

  return {
    json: {
      ...item.json,
      eventId,
      expectedLpn,
      isMatch:
        expectedLpn === null || !actualNormalized
          ? null
          : actualNormalized === expectedNormalized
    }
  };
});

return items.map(item => ({
  json: {
    eventId: item.json.id ?? item.json.eventId ?? null,
    startedAtIso: item.json.startedAtIso ?? null,
    startedAtMs: item.json.startedAtMs ?? null
  }
}));

function extractOutputText(resp) {
  for (const entry of (resp.output || [])) {
    if (entry.type === "message") {
      for (const part of (entry.content || [])) {
        if (part.type === "output_text" && typeof part.text === "string") {
          return part.text;
        }
      }
    }
  }
  return null;
}

function cleanPlate(value) {
  const raw = String(value || '').trim().toUpperCase();

  if (!raw) return null;
  if (['NA', 'N/A', 'N.A', 'N.A.'].includes(raw)) return 'n.a.';

  const compact = raw
    .replace(/[.\s\-_\/\\|]/g, '')
    .replace(/[^A-Z0-9]/g, '');

  if (!compact || compact === 'NA') return 'n.a.';
  return compact;
}

return $input.all().map((item) => {
  const text = extractOutputText(item.json);
  if (!text) throw new Error("No output_text found in LPN Review response");

  const parsed = JSON.parse(text);
  const confidence = Number(parsed.confidence || 0);
  const cleanedFinalPlate = cleanPlate(parsed.finalPlate);

  const forcedNA =
    parsed.decision !== 'POST' ||
    confidence < 0.5 ||
    !cleanedFinalPlate ||
    cleanedFinalPlate === 'n.a.';

  return {
    json: {
      decision: forcedNA ? 'N.A.' : 'POST',
      finalPlate: forcedNA ? 'n.a.' : cleanedFinalPlate,
      chosenRank: forcedNA ? null : (parsed.chosenRank ?? 1),
      selectedFromProvided: null,
      candidateCount: forcedNA ? 0 : 1,
      confidence,
      reason: forcedNA
        ? `forced_n.a.: ${parsed.reason || 'below threshold or invalid plate'}`
        : (parsed.reason || '')
    }
  };
});

