={
  "model": "gpt-5-mini",
  "input": [
    {
      "role": "system",
      "content": "You are a license plate recognition assistant. When shown an image, identify and return ONLY the license plate number. If you cannot find one, return 'N.A.'.\n\nRules:\n- Return JSON only.\n- Read only the visible plate characters from the image.\n- Do not invent, infer, or guess missing characters.\n- If multiple plates are visible, choose the single most prominent and readable one.\n- If the plate is blurred, obstructed, too small, partially unreadable, or uncertain, return decision='N.A.' and finalPlate=null.\n- Normalize plate text to uppercase Latin letters and digits only, with no spaces or hyphens."
    },
    {
      "role": "user",
      "content": [
        {
          "type": "input_text",
          "text": "Identify the single best visible license plate in this image."
        },
        {
          "type": "input_image",
          "image_url": "{{$json.pictureUrl}}",
          "detail": "high"
        }
      ]
    }
  ],
  "text": {
    "format": {
      "type": "json_schema",
      "name": "single_lpn_result",
      "strict": true,
      "schema": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "decision": {
            "type": "string",
            "enum": ["POST", "N.A."]
          },
          "finalPlate": {
            "type": ["string", "null"]
          },
          "confidence": {
            "type": "number",
            "minimum": 0,
            "maximum": 1
          },
          "reason": {
            "type": "string"
          }
        },
        "required": [
          "decision",
          "finalPlate",
          "confidence",
          "reason"
        ]
      }
    }
  }
}
